"""flow.ladder: generated by the graph.py split (P1)."""

from __future__ import annotations

from typing import Any

from ..flow import gates, outcome
from ..flow.gates import ANSWER_REPAIR_TARGETS, DELIVERY_RETRY_MAX, PREPARE_GATE
from .. import state as state_mod
from ..runtime import stage_services
from ..runtime.policy import PolicyError
from ..state import CfuDesignState


def _route_input_target(state: CfuDesignState) -> str:
    """Conditional edge: which benchmark-preparation node to run."""
    return _route_kind(state)[1]


def _route_kind(state: CfuDesignState) -> tuple[str, str]:
    kind = state.get("input_kind") or state.get("input_mode", "natural_language")
    if kind not in ("c_project", "natural_language", "embench"):
        kind = "natural_language"
    if kind == "embench":
        return kind, "prepare_embench_benchmark"
    return kind, ("prepare_c_project_profile" if kind == "c_project" else "create_benchmark_project")


#: Failures the benchmark-preparation rungs treat as a clean, attributable stop.
PREPARE_FAILURES = (PolicyError, ValueError, OSError)


def prepare_failure_handler(state: CfuDesignState, error: Any) -> dict[str, Any]:
    """Node-level LangGraph error handler for the benchmark-preparation rungs.

    Registered through ``add_node(..., error_handler=...)`` (see
    ``flow/policies.py``) instead of a ``try/except`` inside each node. The
    accepted set stays exactly as narrow as it was in the nodes: an unexpected
    exception is a bug, not a denied read, so it is re-raised and the run still
    aborts loudly rather than being "repaired" as if it were a design failure.
    """
    exc = getattr(error, "error", error)
    if not isinstance(exc, PREPARE_FAILURES):
        raise exc
    node = str(getattr(error, "node", "") or PREPARE_GATE)
    return _prepare_failure_update(state, node, exc)


def _prepare_failure_update(state: CfuDesignState, node: str, exc: Exception) -> dict[str, Any]:
    """Turn a benchmark-preparation policy/input error into a clean failure.

    A denied read (for example a C project outside the allowlist) must stop the
    run with ``status=failed`` instead of raising out of the graph.
    """
    message = f"{node} failed: {exc}"
    # Reporting a failure must never mint a run identity: a caller that never
    # went through load_context (and so has no run_id) must not create a fresh
    # run directory just to record its own failure. A real run always has one.
    if str(state.get("run_id", "") or "").strip():
        try:
            stage_services._artifacts_for_stage(state, "prepare_benchmark").write_yaml(
                "prepare_benchmark",
                "04_benchmark/manifest.yaml",
                {"kind": "failed", "node": node, "error": str(exc)},
                status="failed",
            )
        except (PolicyError, OSError, ValueError):
            # Reporting the failure must never mask the original error.
            pass
    return {
        "benchmark_project": {"kind": "failed", "notes": [message]},
        "stage_jobs": "review",
        "stopped_at": PREPARE_GATE,
        "errors": [message],
        **outcome.stage_result(state, rung=PREPARE_GATE, ok=False, node=node,
                               next="review_and_route", errors=[str(exc)], history=message),
    }


def _prepare_gates(state: CfuDesignState, node: str, next_node: str) -> dict:
    return {
        **state.get("gates", {}),
        PREPARE_GATE: {"ok": True, "node": node, "next": next_node},
    }


def _route_after_prepare(state: CfuDesignState) -> str:
    gate = (state.get("gates", {}) or {}).get(PREPARE_GATE, {}) or {}
    return str(gate.get("next") or "review_and_route")


def _route_after_review(state: CfuDesignState) -> str:
    return gates._rung_next(state, "review", "final_report")


def _delivery_retry_transition(
    state: CfuDesignState,
    rung: str,
    target: str,
    ok: bool,
    rejection: bool,
) -> tuple[dict, str] | None:
    """Retry a rejected delivery without spending the design-repair budget.

    ``rejection`` is True only when the implementation stage produced no applied
    change (a deterministic delivery/protocol error). A design that was
    delivered but fails its build is a real repair and keeps using ``--max-iters``.
    """
    if ok or not rejection:
        return None
    retries = int(state.get("delivery_retries", 0) or 0)
    if retries >= DELIVERY_RETRY_MAX:
        return None
    note = (
        f"{rung} not reached: the {target} delivery was rejected by a deterministic "
        f"check and nothing was applied; correcting the delivery "
        f"(retry {retries + 1}/{DELIVERY_RETRY_MAX}) without spending repair budget."
    )
    return {
        "delivery_retries": retries + 1,
        "iteration": int(state.get("iteration", 0) or 0) + 1,
        "stage_jobs": target,
        "errors": [note],
        "iteration_history": state_mod.append_history(state, note),
    }, target


def _ladder_transition(
    state: CfuDesignState,
    rung: str,
    *,
    ok: bool,
    default: str,
    repair_target: str | Any,
    skipped: bool = False,
    repair_kind: str | None = None,
) -> tuple[dict, str]:
    """Decide a rung's successor and the bookkeeping that goes with it.

    Conditional edges cannot update state, so the failing node records its own
    repair/stop decision (``gates.<rung>.next``) and the router only reads it.

    Repair budgets are split by target class: a repair of an answer artifact
    (conformance oracle authored in Implement, ``design_contract``/``extend_isa`` spec) draws
    from ``answer_repairs_used``/``--max-answer-repairs``; a repair of the actual
    design draws from ``repairs_used``/``--max-iters``.
    """
    if ok or skipped:
        return {}, default
    target = repair_target(state) if callable(repair_target) else repair_target
    if repair_kind not in (None, "answer", "design"):
        raise ValueError("repair_kind must be answer or design")
    answer_repair = repair_kind == "answer" or (repair_kind is None and target in ANSWER_REPAIR_TARGETS)
    budget_left = gates._answer_repairs_left(state) if answer_repair else gates._repairs_left(state)
    if budget_left:
        consumed = int(state.get("answer_repairs_used" if answer_repair else "repairs_used", 0) or 0)
        cap = gates.answer_repairs_max(state) if answer_repair else gates.max_repairs(state)
        note = (
            f"{rung} failed; repairing {target} "
            f"(repair {consumed + 1}/{cap})."
        )
        attempts = dict(state.get("attempts", {}) or {})
        attempts[rung] = int(attempts.get(rung, 0)) + 1
        return {
            "attempts": attempts,
            ("answer_repairs_used" if answer_repair else "repairs_used"): consumed + 1,
            "iteration": int(state.get("iteration", 0) or 0) + 1,
            "last_repair_target": target,
            "stage_jobs": target,
            "errors": [note],
            "iteration_history": state_mod.append_history(state, note),
        }, target
    note = (
        f"{rung} failed and no repair budget remains "
        f"(--max-iters {state.get('max_iters', 2)}); stopping the run."
        if not answer_repair
        else (
            f"{rung} failed and the answer-repair budget is exhausted "
            f"(--max-answer-repairs {gates.answer_repairs_max(state)}); stopping the run."
        )
    )
    return {
        "stopped_at": rung,
        "stage_jobs": "review",
        "errors": [note],
        "iteration_history": state_mod.append_history(state, note),
    }, "review_and_route"


def _apply_transition(update: dict, extra: dict) -> dict:
    """Fold a ``_ladder_transition`` payload into a node's state update."""
    extra = dict(extra)
    notes = extra.pop("errors", []) or []
    if notes:
        update["errors"] = [*(update.get("errors") or []), *notes]
    update.update(extra)
    return update


def _route_after_analysis(state: CfuDesignState) -> str:
    return gates._rung_next(state, "analysis", "design_contract")


def _route_after_isa(state: CfuDesignState) -> str:
    return gates._rung_next(state, "isa", "implement")


def _route_after_hw_build(state: CfuDesignState) -> str:
    return gates._rung_next(state, "hw_build", "check_conformance")


def _route_after_hw_conformance(state: CfuDesignState) -> str:
    # The implementation stage already wrote the software, so the ladder simply
    # compiles it: there is no separate software-implementation rung any more.
    return gates._rung_next(state, "hw_conformance", "build_sw")


def _route_after_sw_build(state: CfuDesignState) -> str:
    return gates._rung_next(state, "sw_build", "simulate")


def _route_after_sim(state: CfuDesignState) -> str:
    return gates._rung_next(state, "sim", "estimate_cost")


def _route_after_cost(state: CfuDesignState) -> str:
    return gates._rung_next(state, "cost", "review_and_route")
